"SELECT DISTINCT\r\nCLAIM_ID,\r\n[Current Status] AS \"Original Claim Current Status\",\r\n[Current Status Date] AS \"Original Claim Status Date\",\r\n[Processor ID] AS \"Original Claim Original Processor\"\r\nFROM [Claim Status]\r\n\r\nUNION ALL\r\n\r\nSELECT DISTINCT\r\nNULL AS CLAIM_ID,\r\nNULL AS \"Original Claim Current Status\",\r\nCAST(NULL AS DATETIME) AS \"Original Claim Status Date\",\r\nNULL AS \"Original Claim Original Processor\"\r\nFROM [Claim Status]"
